#include <string>
#include <vector>

std::vector<std::string> dllMainCalls(const std::vector<std::string>& events, bool disableThreadCalls)
{
    std::vector<std::string> calls;
    int references{ 0 };
    for (const std::string& e : events)
    {
        if (e == "load")
        {
            if (references++ == 0) calls.push_back("PROCESS_ATTACH");
        }
        else if (e == "free")
        {
            if (references > 0 && --references == 0) calls.push_back("PROCESS_DETACH");
        }
        else if (e == "thread start")
        {
            if (references > 0 && !disableThreadCalls) calls.push_back("THREAD_ATTACH");
        }
        else if (e == "thread end")
        {
            if (references > 0 && !disableThreadCalls) calls.push_back("THREAD_DETACH");
        }
        else if (e == "exit")
        {
            if (references > 0) calls.push_back("PROCESS_DETACH (exit)");
            break;
        }
    }
    return calls;
}

unitTests:
using Calls = std::vector<std::string>;
TEST("the example") { CHECK_EQ(dllMainCalls({ "thread start", "load", "thread start", "thread end", "free" }, false), (Calls{ "PROCESS_ATTACH", "THREAD_ATTACH", "THREAD_DETACH", "PROCESS_DETACH" })); }
TEST("thread calls disabled") { CHECK_EQ(dllMainCalls({ "load", "thread start", "thread end", "free" }, true), (Calls{ "PROCESS_ATTACH", "PROCESS_DETACH" })); }
TEST("loaded twice") { CHECK_EQ(dllMainCalls({ "load", "load", "free", "thread start", "free" }, false), (Calls{ "PROCESS_ATTACH", "THREAD_ATTACH", "PROCESS_DETACH" })); }
TEST("exit while loaded") { CHECK_EQ(dllMainCalls({ "load", "exit", "thread start" }, false), (Calls{ "PROCESS_ATTACH", "PROCESS_DETACH (exit)" })); }
TEST("free while unloaded") { CHECK_EQ(dllMainCalls({ "free", "load", "free", "free" }, false), (Calls{ "PROCESS_ATTACH", "PROCESS_DETACH" })); }
TEST("exit while unloaded ends it") { CHECK_EQ(dllMainCalls({ "exit", "load" }, false), Calls{}); }

